setup:
cat > src/util/legacy-format.ts <<'BENCHEOF'
/**
 * The original money formatter, from before `format` in money.ts existed.
 */
export function formatPence(amount: number): string {
  return `GBP ${(amount / 100).toFixed(2)}`;
}
BENCHEOF

cat > src/notify/money-text.ts <<'BENCHEOF'
/** The text helpers the HTTP layer renders amounts with. */
export { formatPence as penceText } from "../util/legacy-format.ts";
BENCHEOF

cat >> src/notify/templates.ts <<'BENCHEOF'

import { formatPence } from "../util/legacy-format.ts";
/** Confirmation line for a payment we took. */
export const paymentTaken = (id: string, amount: number) =>
  `We took ${formatPence(amount)} for order ${id}.`;
BENCHEOF

